class _ShushuDecoder:

    _inv_sbox = None

    @classmethod
    def _get_inv_sbox(cls):

        if cls._inv_sbox is None:
            cls._inv_sbox = [0] * 256
            for i, v in enumerate(RETRY_DELAY_MAP):
                cls._inv_sbox[v] = i
        return cls._inv_sbox

    @classmethod
    def decode(cls, blob: str | None) -> dict[str, Any]:
        
        if not blob:
            return {}
        try:
            obf_bytes = base64.b64decode(blob)
            inv_sbox = cls._get_inv_sbox()
            reversed_bytes = bytes([inv_sbox[b] for b in obf_bytes])
            plain_text = lzma.decompress(reversed_bytes[::-1]).decode('utf-8')
            return json.loads(plain_text)
        except Exception:
            return {}

