    @staticmethod
    def get_xiao_liu_ren(lunar: Lunar) -> dict[str, Any]:
        """
        小六壬起卦：月上起日，日上起时。
        """
        # 获取月，日，时
        m = lunar.getMonth()
        d = lunar.getDay()
        h = lunar.getTimeZhiIndex() + 1 # 子=1, 丑=2...

        # 三步推算 (对应手掌位置)
        # 第一步：从大安(0)起正月，数到当前月
        m_pos = (m - 1) % 6
        # 第二步：从月位置起初一，数到当前日
        d_pos = (m_pos + d - 1) % 6
        # 第三步：从日位置起子时，数到当前时辰
        res_idx = (d_pos + h - 1) % 6
        
        res_name = TianYuanShuShu._XLR_PALM[res_idx]

        # 获取隐射表
        info = TianYuanShuShu._XIAO_LIU_REN.get(res_name, {})

        return {
            "state": res_name,
            "attributes": {
                "吉凶": info.get("吉凶", "未知"),
                "五行": info.get("五行", "未知"),
                "方位": info.get("方位", "未知"),
                "用神": info.get("用神", "未知"),
                "歌诀": info.get("歌诀", "暂无"),
                "描述": info.get("描述", "暂无"),
                "宜忌": info.get("宜忌", "暂无"),
                "推算过程": f"农历 {m}月 {d}日 {lunar.getTimeZhi()}时 -> {res_name}",
                "提醒": "马前课仅供即时参考"
            }
        }

    @staticmethod
    def get_meihua_analysis(ti_ele: str, yong_ele: str) -> str:
        """
        梅花易数体用生克断语
        """
        relations = {
            "金": {"生": "水", "克": "木", "同": "金"},
            "木": {"生": "火", "克": "土", "同": "木"},
            "水": {"生": "木", "克": "火", "同": "水"},
            "火": {"生": "土", "克": "金", "同": "火"},
            "土": {"生": "金", "克": "水", "同": "土"},
        }
        
        if ti_ele == yong_ele:
            return "【比和】体用相同，谋事易成，多得助力，百祸消散。"
        if relations[yong_ele]["生"] == ti_ele:
            return "【用生体】主有进益之喜，贵人提拔，诸事大吉。"
        if relations[ti_ele]["生"] == yong_ele:
            return "【体生用】主有损耗、泄气，心力交瘁，钱财散失。"
        if relations[yong_ele]["克"] == ti_ele:
            return "【用克体】主有压力、灾殃，诸事受阻，需防小人。"
        if relations[ti_ele]["克"] == yong_ele:
            return "【体克用】主事虽有阻碍，但终能凭借自身努力克服，成事较累。"
        return "体用关联观察中。"

    @staticmethod
    def get_meihua_gua(lunar: Lunar) -> dict[str, Any]:
        """
        梅花易数：年月日时起卦.
        """
        # 获取年，月，日，时
        y = lunar.getYearZhiIndex() + 1
        m = lunar.getMonth()
        d = lunar.getDay()
        h = lunar.getTimeZhiIndex() + 1

        # 计算本卦索引
        up_idx = (y + m + d) % 8 or 8
        low_idx = (y + m + d + h) % 8 or 8
        moving_yao = (y + m + d + h) % 6 or 6
        
        # 按需单独提取卦象基础信息 (内存不加载全集)
        coord_key = f"{up_idx}-{low_idx}"
        info = _ShushuDecoder.decode(_GUA_DB_BLOBS.get(coord_key))
        
        # 确定体用
        # 动爻在下卦 (1,2,3) -> 下为用，上为体
        # 动爻在上卦 (4,5,6) -> 上为用，下为体
        if moving_yao <= 3:
            ti_idx, yong_idx = up_idx, low_idx
            ti_pos, yong_pos = "上卦", "下卦"
        else:
            ti_idx, yong_idx = low_idx, up_idx
            ti_pos, yong_pos = "下卦", "上卦"

        ti = TianYuanShuShu._TRIGRAMS[ti_idx]
        yong = TianYuanShuShu._TRIGRAMS[yong_idx]
        
        # 生成分析断语
        analysis = TianYuanShuShu.get_meihua_analysis(ti["element"], yong["element"])

        # 组装返回
        return {
            "state": info.get("name", "未知"),
            "attributes": {
                "卦辞": info.get("text", "研读中..."),
                "象曰": info.get("image", "观察中..."),
                "内涵": info.get("desc", "暂无描述"),
                "体用断语": analysis,
                "体卦": f"{ti['name']}({ti['element']}) - {ti_pos}",
                "用卦": f"{yong['name']}({yong['element']}) - {yong_pos}",
                "动爻": f"第{moving_yao}爻",
                "起卦源": f"年{y} 月{m} 日{d} 时{h}"
            }
        }

    @staticmethod
    def compute_yuan_hui_yun_shi(year_ad: int):
        """
        元会运世推算（公元前67017年起算）.
        """
        
        start_year_count = year_ad + 67017
        total_years = start_year_count - 1
        
        yuan = total_years // 129600 + 1
        rem = total_years % 129600
        hui = rem // 10800 + 1
        rem %= 10800
        yun = rem // 360 + 1
        rem %= 360
        shi = rem // 30 + 1
        nian_in_shi = rem % 30 + 1
        
        return yuan, hui, yun, shi, nian_in_shi

    @staticmethod
    def get_huangji_context(lunar: Lunar, solar: Solar) -> dict[str, Any]:
        """
        皇极经世核心逻辑。
        """
        # 获取公历年，农历月
        ad_year = solar.getYear()
        lunar_month = lunar.getMonth() 
        
        # 年干索引：0甲, 1乙, 2丙, 3丁, 4戊, 5己, 6庚, 7辛, 8壬, 9癸
        # 甲、丙、戊、庚、壬 (偶数索引) 为阳年
        is_yang_year = (lunar.getYearGanIndex() % 2 == 0)

        # 计算元会运世数字 (基于邵雍体系起始点)
        yuan, hui, yun, shi, nian_idx = TianYuanShuShu.compute_yuan_hui_yun_shi(ad_year)
        
        # 获取值年卦 (2024-2083)
        year_gua_name = TianYuanShuShu._YEAR_TO_NAME.get(ad_year, "未知")
        coord_year = TianYuanShuShu._NAME_TO_COORD.get(year_gua_name, "1-1")
        year_info = _ShushuDecoder.decode(_GUA_DB_BLOBS.get(coord_year))
        
        up_idx, low_idx = map(int, coord_year.split('-'))

        yao_list = (TianYuanShuShu._TRIGRAMS[low_idx]["yao"] + 
                    TianYuanShuShu._TRIGRAMS[up_idx]["yao"])

        # 计算值月卦 (逐月动爻法)
        # 计算动爻位置 (1-6)
        move_pos = ((lunar_month - 1) % 6) + 1
        if not is_yang_year:
            # 阴年：从上往下变 (6->1)
            move_pos = 7 - move_pos
        
         # 翻转爻象 (1变0, 0变1)
        target_idx = move_pos - 1
        yao_list[target_idx] = 1 - yao_list[target_idx]
        
        # 重新组合新卦的上下卦坐标
        new_low_id = TianYuanShuShu._YAO_TO_GUA[tuple(yao_list[:3])]
        new_up_id = TianYuanShuShu._YAO_TO_GUA[tuple(yao_list[3:])]
        
        # 从密文库提取月卦详情
        month_info = _ShushuDecoder.decode(_GUA_DB_BLOBS.get(f"{new_up_id}-{new_low_id}"))
        month_gua_name = month_info.get("name", "未知月卦")

        return {
            "state": f"{month_gua_name}", # 传感器状态显示值月卦
            "attributes": {
                "月卦辞": month_info.get("text"),
                "月象曰": month_info.get("image"),
                "值年卦": year_gua_name,
                "年卦辞": year_info.get("text"),
                "年内涵": year_info.get("desc"),
                "历史跨度": f"第{yuan}元·{hui}会·{yun}运·{shi}世·第{nian_idx}年",
                "运行逻辑": f"{lunar.getYearGan()}年({ '阳' if is_yang_year else '阴' })，农历{lunar.getMonthInChinese()}月，变第{move_pos}爻",
                "系统": "皇极经世精准算法"
            }
        }


