# 易经详注库类 (IchingLibrary)
# ==========================================        

class IchingLibrary:
    """负责单卦的高级详注提取."""

    @staticmethod
    def get_all_names() -> list[str]:
        return list(_ICHING_BLOBS.keys())

    @classmethod
    def get_gua(cls, name: str) -> dict[str, Any]:

        blob = _ICHING_BLOBS.get(name)
        return _ShushuDecoder.decode(blob)
